import urllib.request,json
base='http://127.0.0.1:17448'
try:
 with urllib.request.urlopen(base+'/api/ai-profiles',timeout=6) as r:d=json.load(r)
 rows=d.get('aiProfiles',[])
 def r(x):
  return {k:x.get(k) for k in ['id','name','provider','debugPort','chromeLaunchMode','attachAutoStart','workerConnected','workerLastSeenAt','enabled','lastLaunchAt','launchError','chromeProfilePath','status'] if k in x and k!='chromeProfilePath'}
 print(json.dumps({'profiles':[r(x) for x in rows],'count':len(rows),'systemKeys':sorted((d.get('system') or {}).keys())[:30],'readOnly':True},ensure_ascii=True)[:3600])
except Exception as e:print(json.dumps({'errorType':type(e).__name__}))
